#!/usr/bin/env node
// scripts/check-prerender-assets.mjs — do the committed static pages point at
// assets this build actually produces?
//
//   npm run build && node scripts/check-prerender-assets.mjs
//
// ── WHY THIS EXISTS ────────────────────────────────────────────────────────
// public/<route>/index.html is GENERATED by scripts/prerender.mjs and COMMITTED,
// deliberately: prerendering during the Netlify build would mean a deploy could
// fail on a Chromium download. The cost of that trade is that the committed
// output can go stale, and the way it goes stale is specific and severe — the
// asset filenames Vite emits are content-hashed, so the moment any source file
// changes, every committed page is referencing a bundle that no longer exists.
//
// That is not a hypothetical. It shipped twice:
//   * all 22 pages referenced index-D0w7-WJI.css / index-DAC99b-7.js from a
//     build on 2026-08-22 — 21 commits after the sources had moved on. Every
//     marketing page loaded unstyled with React never booting, for days.
//   * fixed in c4330e8 — and stale AGAIN within the same session, because two
//     parallel merges touched src/ afterwards.
//
// ── WHY NOT JUST RUN `npm run prerender -- --check` IN CI ──────────────────
// Because that re-renders through a real browser, and a browser is not a pure
// function: a different Chrome build, a different font stack or a different
// serialization order produces a diff that is noise rather than staleness. A
// gate that cries wolf gets bypassed, and a bypassed gate is how the above
// reached production in the first place.
//
// This check is deterministic instead. It reads the asset references out of the
// committed HTML and asks a filesystem question: does dist/ contain this file?
// No browser, no rendering, no possibility of a false positive. It cannot catch
// every kind of drift — copy changes are invisible to it — but it catches the
// one that takes the site down, and it never lies.
//
// The pre-push hook's cheap string heuristic catches "sources moved, output
// didn't" WITHIN one diff. This catches the case that heuristic structurally
// cannot see: drift a merge brought in, with no prerender-feeding file in the
// diff at all.

import { readFileSync, existsSync, readdirSync, statSync } from "node:fs";
import { join, dirname, resolve, relative } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const DIST = join(ROOT, "dist");
const PUBLIC = join(ROOT, "public");

/** Every `/assets/...` URL referenced by an href or src. */
export function assetRefs(html) {
  const out = new Set();
  for (const m of html.matchAll(/(?:href|src)=["'](\/assets\/[^"']+)["']/g)) {
    out.add(m[1]);
  }
  return [...out];
}

/** Generated pages only — hand-written static pages under public/ reference nothing hashed. */
export function generatedPages(dir = PUBLIC, acc = []) {
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) generatedPages(p, acc);
    else if (name === "index.html") {
      const html = readFileSync(p, "utf8");
      if (html.includes("GENERATED by scripts/prerender.mjs")) {
        acc.push({ file: p, rel: relative(ROOT, p), html });
      }
    }
  }
  return acc;
}

function main() {
  if (!existsSync(DIST)) {
    console.error("✗ dist/ not found — run `npm run build` first.");
    process.exit(1);
  }

  const pages = generatedPages();
  if (pages.length === 0) {
    console.error("✗ no generated pages found under public/ — did prerender output move?");
    process.exit(1);
  }

  const missing = [];
  let checked = 0;
  for (const page of pages) {
    const refs = assetRefs(page.html);
    if (refs.length === 0) {
      missing.push(`${page.rel}: references no /assets/ file at all`);
      continue;
    }
    for (const ref of refs) {
      checked++;
      if (!existsSync(join(DIST, ref))) missing.push(`${page.rel} → ${ref}`);
    }
  }

  if (missing.length) {
    console.error(`✗ ${missing.length} asset reference(s) in the committed static pages do not exist in dist/:\n`);
    for (const m of missing.slice(0, 25)) console.error(`    ${m}`);
    if (missing.length > 25) console.error(`    … and ${missing.length - 25} more`);
    console.error(`
  This is the "every marketing page 404s its own JS bundle" failure.
  The committed prerender is stale relative to the current sources.

  Fix:  npm run prerender     then commit all ${pages.length} generated files.
`);
    process.exit(1);
  }

  console.log(`✓ prerender assets: ${pages.length} generated pages, ${checked} asset references, all present in dist/`);
}

if (import.meta.url === `file://${process.argv[1]}`) main();
